int readField(const Player& p, IntMember m) { return p.*m; }

constexpr IntMember kHealth = &Player::health;
constexpr IntMember kArmor  = &Player::armor  ;
constexpr IntMember kMana   = &Player::mana   ;

int v = readField(p, kArmor);
```

### C (X-macro)

```c
