/// - `has_header`: si es `true`, se salta la primera fila y se valida que
///   `column` exista en la cabecera.
///
/// Se ignoran campos vacíos, no numéricos y valores `NaN`/`Inf`.
/// Devuelve `Ok(None)` si no se encontró ningún valor numérico.
pub fn average_of_csv_column<P: AsRef<Path>>(
    path: P,
    column: usize,
    has_header: bool,
) -> io::Result<Option<f64>> {
