    let mut sum: f64 = 0.0;
    let mut compensation: f64 = 0.0;
    let mut count: u64 = 0;

    let mut field = Vec::new();
    let mut is_first = true;

    while let Some(columns_in_record) = stream.next_record(&mut field)? {
        if is_first {
            is_first = false;
            if has_header {
