use std::env;
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;
use std::process;

const READ_BUF: usize = 1 << 20; // 1 MiB read buffer

pub struct CsvReader<R: BufRead> {
    inner: R,
    record: Vec<u8>,             // bytes of the current record, reused
    fields: Vec<(usize, usize)>, // (start, end) ranges into record
    skip_lf: bool,               // pending \n after a \r split across buffers
}

impl<R: BufRead> CsvReader<R> {
    pub fn new(inner: R) -> Self {
        Self {
            inner,
            record: Vec::with_capacity(16 * 1024),
            fields: Vec::with_capacity(32),
            skip_lf: false,
        }
    }

    pub fn field(&self, idx: usize) -> Option<&[u8]> {
        self.fields.get(idx).map(|&(s, e)| &self.record[s..e])
    }

    /// Reads next record. Returns Ok(false) on clean EOF.
    pub fn next_record(&mut self) -> io::Result<bool> {
        let Self { inner, record, fields, skip_lf } = self;
        record.clear();
        fields.clear();

        // If previous record ended on a bare \r at a buffer boundary,
        // swallow a leading \n here.
        if *skip_lf {
            *skip_lf = false;
            let skip = {
                let buf = inner.fill_buf()?;
                !buf.is_empty() && buf[0] == b'\n'
            };
            if skip {
                inner.consume(1);
            }
        }

        let mut in_quotes = false;
        let mut field_start = 0usize;
        let mut started = false;

        loop {
            let buf = inner.fill_buf()?;
            if buf.is_empty() {
                if !started {
                    return Ok(false);
                }
                fields.push((field_start, record.len()));
                return Ok(true);
            }

            let mut i = 0usize;
            let mut record_done = false;
            while i < buf.len() {
                let b = buf[i];
                i += 1;
                started = true;

                if in_quotes {
                    if b == b'"' {
                        // `""` inside a quoted field -> literal `"`
                        if i < buf.len() && buf[i] == b'"' {
                            record.push(b'"');
                            i += 1;
                        } else {
                            in_quotes = false;
                        }
                    } else {
                        record.push(b);
                    }
                    continue;
                }

                match b {
                    b'"' => in_quotes = true,
                    b',' => {
                        fields.push((field_start, record.len()));
                        field_start = record.len();
                    }
                    b'\n' => {
                        record_done = true;
                        break;
                    }
                    b'\r' => {
                        if i < buf.len() {
                            if buf[i] == b'\n' {
                                i += 1;
                            }
                        } else {
                            *skip_lf = true;
                        }
                        record_done = true;
                        break;
                    }
                    _ => record.push(b),
                }
            }
            inner.consume(i);
            if record_done {
                fields.push((field_start, record.len()));
                return Ok(true);
            }
        }
    }
}

