    v := strings.TrimSpace(u.Nombre)
    if v == "" { return "—" }
    return v
}

func Email(u Usuario) string {
    v := strings.TrimSpace(u.Email)
    if v == "" { return "—" }
    return v
}

func Telefono(u Usuario) string {
