func campo(get func(Usuario) string) func(Usuario) string {
    return func(u Usuario) string { return normalizar(get(u)) }
}

var (
    Nombre   = campo(func(u Usuario) string { return u.Nombre })
    Email    = campo(func(u Usuario) string { return u.Email })
    Telefono = campo(func(u Usuario) string { return u.Telefono })
